    "clinicalCase": "Um homem de 28 anos é trazido ao hospital pelo SAMU 40 minutos após ter sofrido atropelamento. Ele foi encontrado desacordado no local do acidente, apresentando Glasgow 6. Ao chegar à unidade de saúde, apresentava Glasgow 3, pressão arterial de 150 × 100 mmHg, irregularidade respiratória e frequência cardíaca de 50 batimentos por minuto, sendo realizada a intubação orotraqueal. Ao exame físico, apresenta- se em mau estado geral, paciente em uso de ventilação mecânica com ausência de ruídos adventícios à ausculta respiratória. O paciente está comatoso, com Glasgow 3 e com pupilas isocóricas e midriáticas, constata-se, ainda, reflexos fotomotores direto e consensual ausentes; reflexo córneo- palpebral ausente e reflexo óculo-cefálico ausente. Paciente sem sedação. Foi levantada a hipótese diagnóstica de hipertensão intracraniana pela equipe médica. Diante dessas informações, o achado clínico que confirma essa hipótese é a presença de",
