    "clinicalCase": "Uma menina de 6 anos viajou de férias com a família para a República Dominicana, onde permaneceu por 10 dias. Na véspera do retorno ao Brasil, a paciente apresentou febre baixa, evoluindo, em 24 horas, para um quadro com diarreia súbita, líquida e abundante. Ao desembarcarem no aeroporto, ela foi prontamente atendida pela equipe da ANVISA, que a encaminhou ao hospital para avaliação, devido à suspeita de cólera. Tendo em vista a exuberância dos sintomas e o grau de desidratação, ao chegar ao hospital, a paciente é internada imediatamente. No hospital, são coletadas amostras de fezes, com resultado positivo para Vibrio cholerae. Durante a internação hospitalar, a paciente recebe, além de reidratação endovenosa e de sulfato de zinco, antibioticoterapia com doxiciclina (3 mg/kg em dose única). Nessa circunstância, as medidas de prevenção e de controle pertinentes ao quadro apresentado por essa paciente incluem",
