    "clinicalCase": "Um recém-nascido (RN) a termo, afrodescendente, do sexo masculino, com 26 dias, apresenta quadro de icterícia neonatal zona III de Kramer desde o 3.o dia de vida. Seus pais negam outras queixas e afirmam que ambos são consanguíneos (primos). Encontra-se em uso de fórmula láctea com ganho ponderal adequado. Não houve intercorrências na gestação e parto. Diante dessas informações, o médico solicita outros exames. A criança, então, retorna à consulta ambulatorial com propedêutica complementar solicitada há 7 dias. Os resultados dos exames realizados podem ser verificados a seguir. A tipagem sanguínea da mãe é O+ e do recém-nascido é A-. O Coombs direto (ou teste de antiglobulina direto) apresenta resultado negativo. Exame laboratorial Resultado Valor de referência Hemoglobina 12 g/dL 12,5 a 20,5 g/dL Hematócrito 36% 39 a 63% VCM 80 fL 86 a 124 fL HCM 26 pg 28 a 40 pg CHCM 25 g/dL 28 a 38 g/dL Plaquetas 450.000/mm3 250.000 a 500.000/mm3 Reticulócitos 6,4 % 2,0 a 6,0% Bilirrubinas totais 12,8 mg/dL RN 3 - 5 dias: 10,30 mg/dL Bilirrubinas diretas 0,8 mg/dL RN 3 - 5 dias: até 0,4 mg/dL Bilirrubinas indiretas 12,0 g/dL TSH 5 μU/mL < 10 μU/mL Considerando-se o caso clínico e os exames complementares realizados, qual é a hipótese diagnóstica mais provável?",
