        "explanation": "Em morte natural domiciliar com causa conhecida e sem indícios de violência, a declaração de óbito deve ser preenchida pelo médico assistente; a broncopneumonia é registrada como causa básica, a DPOC como antecedente e HAS, hemiplegia e AVC como causas contribuintes."
