    "clinicalCase": "Em certo município brasileiro, a gestão da saúde é feita de forma centralizada: todas as decisões e ações são tomadas por um pequeno grupo de gestores sem a participação efetiva da população. Isso tem gerado descontentamento e desconfiança por parte dos cidadãos, que sentem que suas necessidades e demandas não estão sendo consideradas. Um grupo de moradores, então, decide organizar-se para reivindicar maior participação no processo de gestão da saúde. A primeira medida que esses moradores tomam é buscar informações sobre o controle social no SUS. Esse grupo de moradores descobriu, com base na lei n. 8.142 de 1990 e no Decreto n. 7.508 de 2011, que eles têm o direito de",
