    "clinicalCase": "Uma paciente de 39 anos, G2 PV1, com idade gestacional de 40 semanas (calculada por ecografia obstétrica de 10 semanas de idade gestacional), procura sua maternidade de referência. Ela refere movimentação fetal e nega perdas de líquido ou sangramento vaginal. Está em uso de metildopa 750 mg/dia, por hipertensão gestacional, com bom controle pressórico. A paciente tem fator ABO Rh: A+ e realizou todas as rotinas laboratoriais do pré-natal, as quais estavam normais. Sua última ecografia obstétrica com Doppler foi realizada há 4 semanas e evidenciou feto único, cefálico, com índice de líquido amniótico normal, peso fetal no percentil 20 e circunferência abdominal fetal no percentil 30. O Doppler obstétrico apresentou-se normal. Ao exame físico, apresenta-se afebril, eupneica com frequência cardíaca de 88 batimentos por minuto, pressão arterial de 127 × 66 mmHg. Ao exame físico obstétrico, identifica-se altura uterina de 34 cm, movimentação fetal presente, dinâmica uterina ausente e índice de Bishop de 8. À carditocografia, identificou-se aumento abrupto da frequência cardíaca fetal, com ápice maior ou igual a 15 batimentos por minuto e duração maior ou igual a 15 segundos; batimento cardíaco fetal basal de 130 batimentos por minuto e variabilidade da frequência cardíaca fetal de 20 batimentos por minuto. Nesse caso, conforme o Manual de Gestação de Alto Risco do Ministério da Saúde (2022), qual é a conduta médica adequada?",
