    "clinicalCase": "Uma mulher de 33 anos procura atendimento médico, referindo ter notado há 3 meses, durante autoexame das mamas, nodulação no quadrante súperolateral da mama direita. Não notou aumento de volume ou de tamanho do nódulo durante esse tempo. Relata ter mais facilidade de identificar o nódulo no período que antecede a menstruação e nega outras queixas associadas. É tabagista (10 cigarros/dia), corre – 4 vezes por semana –, engravidou uma única vez (parto normal, há dois anos), amamentou por 6 meses, faz uso de DIU de cobre, com boa adaptação. Sua menarca foi aos 11 anos, sexarca aos 18 anos, possui ciclos regulares (5-28), sua última menstruação foi há 15 dias. Relata história familiar de câncer de ovário (tia materna aos 47 anos) e de câncer de mama (sua mãe aos 42 anos). Ao exame físico, observa-se nódulo palpável em quadrante súperolateral da mama direita, com cerca de 3 cm; móvel, com consistência macia e limites definidos; sem outros achados. O ultrassom de mamas e axilas, realizado 20 dias após a consulta, revelou BIRADS 2 — observada lesão anecóica circunscrita, com reforço acústico posterior, sem septações, sem fluxo ao Doppler, em quadrante súperolateral da mama direita, medindo 2 cm em seu maior diâmetro. Nesse caso, conforme as recomendações do Ministério da Saúde, quais são, respectivamente, a hipótese diagnóstica e a conduta adequada?",
